import corpus from "@/content/articles.json";
import type { Cover } from "@/lib/article-cover";

/**
 * One of my Medium articles, as generated by scripts/build-articles.ts from
 * the Medium export. SERVER ONLY: this module imports every article body, so
 * it must never be imported from a client component. The page's article
 * count comes from content/articles-meta.json instead (see lib/content.ts).
 */
export type Article = {
  slug: string;
  title: string;
  url: string;
  publishedAt: string;
  publication?: string;
  /** Set on joint articles (published under someone else's byline): who I co-wrote it with. */
  coAuthors?: string[];
  /** One plain sentence: what it's actually about (titles are often puns). */
  summary: string;
  /** 3–6 retrieval keywords. */
  keywords: string[];
  /** Headings in order (stage-2 input). */
  outline: string[];
  /** First ~800 chars of prose (stage-2 input). */
  intro: string;
  /** Full text, Markdown. */
  body: string;
  /** Section key (lib/article-sections.ts) → one plain sentence on what it covers. Absent until the build drafts them. */
  sectionNotes?: Record<string, string>;
  words: number;
  /** The post's first picture, on Medium's CDN (lib/article-cover.ts). Absent when the post has none. */
  cover?: Cover;
};

/**
 * Imported statically so Vercel's file tracing bundles it with the function.
 * Via `unknown`: TypeScript infers each article's sectionNotes as an object of
 * its own literal heading keys, which doesn't overlap Record<string, string>
 * across articles. The build script is what guarantees the shape.
 */
export const ARTICLES = corpus as unknown as Article[];
